export function synopsis(cmd: Command): string {
  let usage = cmd.usage;
  if (Object.keys(cmd.subcommands).length && !cmd.subcommand_required) {
    usage = usage.replace("<SUBCOMMAND>", "[SUBCOMMAND]");
  }
  // The completion spec replaces run's arguments with a dynamic project-task mount.
  if (cmd.mounts.some((mount) => mount.run === "mise tasks --usage")) {
    usage += " [TASK] [ARGS]…";
  }
  return `mise ${usage}`.trim();
}

/** Fence only real indented code tokens, preserving lists and existing fences. */
export function fenceCodeBlocks(source: string): string {
  const lines = source.split("\n");
  const blocks = markdown.parse(source, {}).filter((token) => token.type === "code_block");
  for (const token of blocks.reverse()) {
    const [start, end] = token.map!;
    const content = token.content.replace(/\n$/, "");
    const first = content.split("\n")[0];
    const indent = Math.max(0, lines[start].indexOf(first) - 4);
    const prefix = " ".repeat(indent);
    const longest = Math.max(2, ...[...content.matchAll(/`+/g)].map((match) => match[0].length));
    const fence = "`".repeat(longest + 1);
    lines.splice(start, end - start, prefix + fence, ...content.split("\n").map((line) => prefix + line), prefix + fence);
  }
  return lines.join("\n");
}

export function commandIndex(root: Command): string {
  const remaining = new Map(Object.entries(root.subcommands).filter(([, cmd]) => !cmd.hide));
  const sections: string[] = [];
  for (const [heading, names] of [...categories, ["Other commands", [...remaining.keys()].join(" ")]]) {
    const rows: string[] = [];
    for (const name of names.split(" ")) {
      const cmd = remaining.get(name);
      if (!cmd) continue;
      remaining.delete(name);
      rows.push(`- [\`mise ${name}\`](/cli/${name}.html) — ${cmd.help ?? "Command reference"}`);
    }
    if (rows.length) sections.push(`### ${heading}\n\n${rows.join("\n")}`);
  }
  return `## Subcommands\n\nChoose a command family below. Its page lists the available subcommands.\n\n${sections.join("\n\n")}`;
}

function sourcePath(url: string): string {
  const path = url.split("#")[0];
  return resolve(docsDir, path.slice(1).replace(/\.html$/, ".md") + (path.endsWith("/") ? "index.md" : ""));
}

function main() {
  const root = JSON.parse(execFileSync("usage", ["generate", "json", "--file", "mise.usage.kdl"], { encoding: "utf8" })).cmd as Command;
  const commands = new Map<string, Command>();
  function visit(cmd: Command) {
    commands.set(cmd.full_cmd.join(" "), cmd);
    Object.values(cmd.subcommands).forEach(visit);
  }
  visit(root);
  for (const [label, url] of Object.values(guides)) {
    if (!existsSync(sourcePath(url))) throw new Error(`Missing guide: ${label} (${url})`);
  }
  let count = 0;
  for (const [name, cmd] of commands) {
    const file = resolve(docsDir, "cli", name ? `${name.replaceAll(" ", "/")}.md` : "index.md");
    if (!existsSync(file)) continue; // usage excludes hidden commands' own pages.
    let page = readFileSync(file, "utf8").split(navigationMarker)[0].trimEnd();
    if (name) {
      page = page.replace(/^- \*\*Usage:\*\* `[^\n]+`/m, `- **Usage:** \`${synopsis(cmd)}\``);
      // When the first child is hidden, usage omits the subcommand heading.
      if (!page.includes("## Subcommands")) {
        page = page.replace(/\n- \[`mise [^\n]+\]\(\/cli\//, (match) => "\n\n## Subcommands\n" + match);
      }
      const parts = name.split(" ");
      let guide: [string, string] | undefined;
      for (let i = parts.length; i > 0 && !guide; i--) guide = guides[parts.slice(0, i).join(" ")];
      guide ??= ["Getting started", "/getting-started.html"];
      let parent = parts.slice(0, -1);
      while (parent.length && !existsSync(resolve(docsDir, "cli", parent.join("/") + ".md"))) parent.pop();
      const parentLink = parent.length ? `[\`mise ${parent.join(" ")}\`](/cli/${parent.join("/")}.html)` : "[All commands](/cli/)";
      const hiddenParent = parts.slice(0, -1).some((_, i) => commands.get(parts.slice(0, i + 1).join(" "))?.hide);
      let compatibility = "";
      if (hiddenParent) {
        const canonical = name.replace("bootstrap launchd", "bootstrap macos launchd-agents").replace("bootstrap systemd", "bootstrap linux systemd-units").replace("bootstrap macos-defaults", "bootstrap macos defaults");
        if (canonical !== name && commands.has(canonical)) compatibility = `\nThis is a compatibility spelling. Use [\`mise ${canonical}\`](/cli/${canonical.replaceAll(" ", "/")}.html) in new scripts.\n`;
      }
      page += `\n\n${navigationMarker}\n${compatibility}\n## Related documentation\n\n- [${guide[0]}](${guide[1]}).\n- ${parentLink}.\n- [Global flags and argument syntax](/cli/#global-flags).\n`;
    } else {
      page = page.replace(/\*\*Usage:\*\* `[^\n]+`/, "**Usage:** `mise [FLAGS] [COMMAND | TASK] [ARGS]…`");
      page = page.replace(/^- \*\*Usage:\*\*[^\n]+\n/m, "");
      page = page.slice(0, page.indexOf("## Subcommands")) + commandIndex(root) + "\n";
      page = page.replace("## Arguments", "Use `mise COMMAND --help` for the help shipped with your installed version. Put mise\nflags before a task name; arguments after the name are passed to that task.\nSquare brackets mark optional input, angle brackets mark required input, and `…`\nmeans the argument can repeat. Do not type those notation characters.\n\n## Arguments");
      page = page.replace("## Global Flags", "## Global Flags\n\nThese flags provide shared context. A command can define its own flag with the same\nname, so consult that command's page for placement and meaning. Effect labels describe\nthe command's intended operation; configuration evaluation, caches, and required tool\ninstallation can still have side effects. They are not sandbox guarantees.\n");
    }
    // Keep every linked synopsis consistent with the command's own page.
    page = page.replace(/\[`mise [^\n]+?`\]\(\/cli\/([^)]*)\.md\)/g, (match, path: string) => {
      const child = commands.get(path.replaceAll("/", " "));
      return child ? `[\`${synopsis(child)}\`](/cli/${path}.html)` : match;
    });
    page = page.replace(/^Examples:\s*$/gm, "## Examples");
    page = fenceCodeBlocks(page);
    writeFileSync(file, page.trimEnd() + "\n");
    count++;
  }
  console.log(`Added reference navigation to ${count} CLI pages`);
}

if (import.meta.main) main();
